verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
// Comments out, then every run of whitespace to ONE space. A probe that fails because a line was
// wrapped or a space dropped is not measuring a consequence, it is measuring today’s formatting,
// and its message then names a regression that did not happen.
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ").replace(/\s+/g," ")
const read=(p)=>{try{return norm(fs.readFileSync(p,"utf8"))}catch{return null}}
const dir="app/(main)/spaces/[slug]/settings/calendar/"
const grid=read("components/events/event-calendar.tsx"),store=read("lib/events/store.ts"),admin=read("lib/calendar/admin-calendar.ts")
const vera=read(dir+"vera-calendar-actions.ts"),wf=read("components/spaces/calendar-workflow-view.tsx")
const drawer=read(dir+"plan-drawer.tsx"),details=read("components/calendar-suite/suite-details.tsx"),quick=read("components/calendar-suite/suite-quick.tsx"),pii=read("lib/calendar/planner/pencil-it-in.ts"),voc=read("lib/calendar/vera-command.ts")
if([grid,store,admin,vera,drawer,details,quick,pii,voc].some((s)=>s===null))process.exit(79)
const between=(s,a,b)=>{const i=s.indexOf(a);if(i<0)return "";const j=b?s.indexOf(b,i):-1;return j<0?s.slice(i):s.slice(i,j)}
Promise.all([import("@/lib/calendar/sunday-stack.ts"),import("@/lib/events/series.ts"),import("@/lib/calendar/month-window.ts")]).then(([sun,series,win])=>{
// (1) A SEGMENT PER ITEM, AND ONLY FOR A RUN. Run the grouping rather than grepping for the name of
// the abutting test: two items that merely share a day are two chips, two that abut are one block.
const at=(slug,startInstantIso)=>({slug,title:slug,dayKey:"2026-09-20",timeLabel:"x",whenLabel:"x",startInstantIso,location:null,goingCount:0,coverUrl:null,isCancelled:false})
const abut=sun.stackRuns([at("a","2026-09-20T16:00:00.000Z"),at("b","2026-09-20T19:00:00.000Z")])
const apart=sun.stackRuns([at("a",null),at("b",null)])
const hoursApart=sun.stackRuns([at("a","2026-09-20T02:00:00.000Z"),at("b","2026-09-20T20:00:00.000Z")])
if(abut.length!==1||abut[0].length!==2)fail("two back-to-back items on a day no longer stack into one block, so a busy Sunday is a column of truncated chips again")
if(apart.length!==2)fail("any two items on a day stack again, so the second gathering on that day cannot be opened from the grid and the \x22+N more\x22 count is swallowed")
if(hoursApart.length!==2)fail("two TIMED items hours apart on one day stack again: the abutting window no longer means abutting, so a morning sit and an evening talk merge into one chip that opens only the first")
const day=sun.stackDay([at("a",null),at("b",null)])
if(day.flatMap((d)=>d.runs).reduce((n,r)=>n+r.length,0)!==2)fail("stackDay drops items on its way to runs, so a cell shows fewer gatherings than the day holds")
if(/cards\.map\(\(\w+\) => \w+\.title\)\.join/.test(grid))fail("the grid still joins every title of a busy day into ONE chip, so the second gathering on that day cannot be opened from the grid")
if(!/stackDay\(/.test(grid)||!/\.runs/.test(grid)||!/data-calendar-stack/.test(grid))fail("the grid does not render a button per item out of stackDay runs")
if(/stackDay\((?:[^()]|\([^()]*\))*\) ?\[0\]/.test(grid))fail("the grid reads only the FIRST of stackDay groups, so a cell holding a multi-day item keeps that item and drops the date own")
// (2) THE TEAM READ HAS A FLOOR. Run the floor, then check the read applies one — in three separate
// arms, so hoisting the floor into a local (behaviour-identical) is not reported as a lost floor.
const floor=series.seriesUpcomingFloor("2026-09-20")
if(typeof floor!=="string"||floor.slice(0,10)>"2026-09-20")fail("seriesUpcomingFloor no longer returns a floor at or below the day it is given, so a series that started before today drops out of the team read")
const day0=win.adminEventFloorDay(new Date("2026-09-20T12:00:00.000Z"))
if(!/^\d{4}-\d{2}-\d{2}$/.test(day0)||day0>"2026-09-20")fail("adminEventFloorDay no longer returns a day key at or below today, so the Admin read starts in the wrong place")
if(!/opts\.fromDay/.test(store))fail("listEventsForSpace ignores fromDay, so the team read is the oldest 200 events again")
if(!/seriesUpcomingFloor\(/.test(store))fail("listEventsForSpace no longer derives its floor from seriesUpcomingFloor, so a repeating gathering that began before today disappears from the team read")
if(!/\.gte\(\x27starts_at\x27,/.test(store))fail("listEventsForSpace applies no starts_at floor, so the team read is the oldest 200 events again")
if(admin.split("listEventsForSpace(").length-1<1||!/fromDay: ?adminEventFloorDay\(now\)/.test(admin))fail("the team calendar read carries no floor, so a Space past 200 events loses its upcoming ones from Admin, List, Workflow and the count")
if(!/listOwnedEventRows\(spaceId, ?now\)/.test(between(admin,"export async function listPlanLinkableEventRows")))fail("the Link an event picker reads a different window from the grid")
// (3) VERA ARCHIVE TAKES THE DATES WITH IT
const arch=between(vera,"case \x27archive\x27").slice(0,500)
if(!/archiveSpacePlan\(slug, ?change\.planId\)/.test(arch)||/archived_at/.test(arch))fail("Vera archive only stamps archived_at, so pencilled dates stay on the grid tied to a hidden Plan")
if(/Nothing is deleted/.test(voc))fail("the review line still says nothing is deleted while pencilled dates go")
// (4) CANCELLED ASKS FIRST, AND ONE CARD PENDS
if(wf!==null){const onChange=between(wf,"onChange={(event)","transitionPlanStage(")
if(!onChange.includes("\x27cancelled\x27"))fail("the Workflow stage select no longer singles out Cancelled, so archiving a Plan is one of six ordinary choices")
if(!/window\.confirm\(/.test(onChange))fail("choosing Cancelled on a Workflow card archives the Plan with no confirm")
if(!/pendingPlanId === card\.plan\.id/.test(wf)||/disabled=\{pending\}/.test(wf))fail("one stage change still disables every card on Workflow")}
// (5) THE PLAN DRAWER
if(!/useState<string\[\] ?\| ?null>\( ?null ?\)/.test(drawer))fail("Readiness reads Ready before planReadiness returns")
if(!/\.catch\(/.test(between(drawer,"planReadiness(slug, plan.id, entryId ?? null)","listPlanLinkableEvents(slug)")))fail("a failed readiness read is swallowed and reads Ready")
const again=drawer.slice(drawer.lastIndexOf("<Button",drawer.indexOf("Run it again")),drawer.indexOf("Run it again"))
if(!/disabled=\{pending\}/.test(again)||!/setNotice\(/.test(again))fail("Run it again can fire twice or says nothing")
if(!/onKeyDown=\{enterAddsTodo\}/.test(drawer))fail("Enter in the to-do input submits the Save Plan form and closes the drawer")
// (6) THE STAFF GRID SAYS WHAT CANCEL DOES, AND THE SHORT FORM OFFERS A TYPE
if(!/item\.plan \? \x27Cancel the Plan\x27 : \x27Cancel\x27/.test(details))fail("Cancel on a Plan-linked date still hides that it cancels the whole Plan")
if(!/SegmentedControl label=\x22Kind\x22/.test(quick))fail("the quick add offers no Kind, so every + makes a Plan")
if(/planId/.test(pii.slice(pii.indexOf("export function quickEntry"),pii.indexOf("export function pencilDoneLine"))))fail("a private or unavailable quick add now carries a Plan")
process.exit(0)
}).catch((e)=>{console.error("probe could not look: "+e.message);process.exit(79)})'
